CREATE TABLE public.user_saved_takeaways (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, section_id uuid NOT NULL REFERENCES public.module_sections(id) ON DELETE CASCADE, takeaway_text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,section_id));
GRANT SELECT,INSERT,DELETE ON public.user_saved_takeaways TO authenticated;
GRANT ALL ON public.user_saved_takeaways TO service_role;
ALTER TABLE public.user_saved_takeaways ENABLE ROW LEVEL SECURITY;
CREATE POLICY saved_read ON public.user_saved_takeaways FOR SELECT TO authenticated USING ((SELECT auth.uid())=user_id);
CREATE POLICY saved_insert ON public.user_saved_takeaways FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid())=user_id);
CREATE POLICY saved_delete ON public.user_saved_takeaways FOR DELETE TO authenticated USING ((SELECT auth.uid())=user_id);
CREATE OR REPLACE FUNCTION public.practice_eligible(_module_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.module_sections s JOIN public.user_section_progress p ON p.section_id=s.id WHERE s.module_id=_module_id AND p.user_id=auth.uid() AND p.completed); $$;
CREATE OR REPLACE FUNCTION public.get_mistake_questions(_limit integer DEFAULT 10) RETURNS TABLE(id uuid,module_id uuid,question text,options jsonb,order_index integer,section_id uuid,is_checkpoint boolean,position_in_section integer,exercise_type text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN QUERY SELECT q.id,q.module_id,q.question,q.options,q.order_index,q.section_id,q.is_checkpoint,q.position_in_section,q.exercise_type FROM public.quiz_questions q CROSS JOIN LATERAL (SELECT p.is_correct,p.created_at FROM public.user_quiz_performance p WHERE p.user_id=auth.uid() AND p.question_id=q.id ORDER BY p.created_at DESC,p.attempt_number DESC,p.id DESC LIMIT 1) latest WHERE NOT latest.is_correct AND public.practice_eligible(q.module_id) ORDER BY latest.created_at,q.id LIMIT greatest(0,least(coalesce(_limit,10),10)); END $$;
CREATE OR REPLACE FUNCTION public.get_mistake_count() RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN (SELECT count(*) FROM public.quiz_questions q CROSS JOIN LATERAL (SELECT p.is_correct FROM public.user_quiz_performance p WHERE p.user_id=auth.uid() AND p.question_id=q.id ORDER BY p.created_at DESC,p.attempt_number DESC,p.id DESC LIMIT 1) latest WHERE NOT latest.is_correct AND public.practice_eligible(q.module_id)); END $$;
CREATE OR REPLACE FUNCTION public.get_rapid_fire_items(_limit integer DEFAULT 10) RETURNS TABLE(id uuid,question text,option_text text,option_index integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN QUERY WITH picked AS (SELECT q.*,row_number() OVER(ORDER BY random()) rn FROM public.quiz_questions q WHERE NOT coalesce(q.is_checkpoint,false) AND coalesce(q.exercise_type,'multiple_choice')='multiple_choice' AND public.practice_eligible(q.module_id) AND jsonb_array_length(q.options)>1 ORDER BY random() LIMIT greatest(0,least(coalesce(_limit,10),10))) SELECT q.id,q.question,q.options->>choice.idx,choice.idx FROM picked q CROSS JOIN LATERAL (SELECT CASE WHEN q.rn%2=0 THEN q.correct_answer ELSE (SELECT i FROM generate_series(0,jsonb_array_length(q.options)-1) i WHERE i<>q.correct_answer ORDER BY random() LIMIT 1) END idx) choice ORDER BY random(); END $$;
CREATE OR REPLACE FUNCTION public.check_rapid_fire(_question_id uuid,_option_index integer,_claimed_true boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quiz_questions%ROWTYPE; right_answer boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO q FROM public.quiz_questions WHERE id=_question_id; IF NOT FOUND OR NOT public.practice_eligible(q.module_id) THEN RAISE EXCEPTION 'Question unavailable'; END IF; IF _option_index IS NULL OR _option_index<0 OR _option_index>=jsonb_array_length(q.options) THEN RAISE EXCEPTION 'Invalid option'; END IF; right_answer:=coalesce((_option_index=q.correct_answer)=_claimed_true,false); RETURN jsonb_build_object('is_correct',right_answer,'correct_option_text',q.options->>q.correct_answer,'explanation',coalesce(CASE WHEN right_answer THEN q.explanation_correct ELSE q.explanation_wrong END,q.explanation,'')); END $$;
CREATE OR REPLACE FUNCTION public.has_match_content() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN EXISTS(SELECT 1 FROM public.quiz_questions q WHERE q.exercise_type='drag_match' AND jsonb_typeof(q.match_pairs)='array' AND jsonb_array_length(q.match_pairs)>=5 AND public.practice_eligible(q.module_id)); END $$;
CREATE OR REPLACE FUNCTION public.get_match_sets(_limit integer DEFAULT 1) RETURNS TABLE(id uuid,question text,left_items jsonb,right_items jsonb) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN QUERY SELECT q.id,q.question,(SELECT jsonb_agg(x.term ORDER BY random()) FROM (SELECT p->>'term' term FROM jsonb_array_elements(q.match_pairs) p LIMIT 5) x),(SELECT jsonb_agg(x.definition ORDER BY random()) FROM (SELECT p->>'definition' definition FROM jsonb_array_elements(q.match_pairs) p LIMIT 5) x) FROM public.quiz_questions q WHERE q.exercise_type='drag_match' AND jsonb_typeof(q.match_pairs)='array' AND jsonb_array_length(q.match_pairs)>=5 AND public.practice_eligible(q.module_id) ORDER BY random() LIMIT greatest(0,least(coalesce(_limit,1),1)); END $$;
CREATE OR REPLACE FUNCTION public.check_match(_question_id uuid,_pairs jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quiz_questions%ROWTYPE; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT * INTO q FROM public.quiz_questions WHERE id=_question_id AND exercise_type='drag_match'; IF NOT FOUND OR NOT public.practice_eligible(q.module_id) THEN RAISE EXCEPTION 'Question unavailable'; END IF; IF jsonb_typeof(_pairs)<>'array' OR jsonb_array_length(_pairs)>5 THEN RAISE EXCEPTION 'Invalid pairs'; END IF; RETURN (SELECT jsonb_agg(jsonb_build_object('term',p->>'term','definition',p->>'definition','is_correct',EXISTS(SELECT 1 FROM jsonb_array_elements(q.match_pairs) actual WHERE actual->>'term'=p->>'term' AND actual->>'definition'=p->>'definition'))) FROM jsonb_array_elements(_pairs) p); END $$;
CREATE OR REPLACE FUNCTION public.award_practice_xp(_mode text,_session_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); day_start timestamptz:=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'; today_xp integer; total_today integer; old public.user_learning_stats%ROWTYPE; streak integer; freezes integer; freeze_used boolean:=false; day date:=(now() AT TIME ZONE 'UTC')::date; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF _mode NOT IN ('mistakes','rapid','flash','match') OR _mode IS NULL OR _session_key IS NULL OR _session_key !~ ('^'||_mode||':'||day::text||':[1-9][0-9]*$') THEN RAISE EXCEPTION 'Invalid practice session'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_badges WHERE user_id=uid) THEN RAISE EXCEPTION 'Earn your first badge first'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,1)); SELECT coalesce(sum(xp_amount),0) INTO today_xp FROM public.xp_transactions WHERE user_id=uid AND source='practice_tab' AND created_at>=day_start AND created_at<day_start+interval '1 day'; IF EXISTS(SELECT 1 FROM public.xp_transactions WHERE user_id=uid AND source='practice_tab' AND source_id=_session_key AND created_at>=day_start AND created_at<day_start+interval '1 day') THEN RAISE EXCEPTION 'Practice session already rewarded'; END IF; SELECT coalesce(sum(xp_amount),0) INTO total_today FROM public.xp_transactions WHERE user_id=uid AND created_at>=day_start AND created_at<day_start+interval '1 day'; IF today_xp>=30 OR total_today+5>400 THEN RETURN jsonb_build_object('awarded',0,'today_total',today_xp); END IF; INSERT INTO public.user_learning_stats(user_id) VALUES(uid) ON CONFLICT(user_id) DO NOTHING; SELECT * INTO old FROM public.user_learning_stats WHERE user_id=uid FOR UPDATE; streak:=old.current_streak; freezes:=old.streak_freezes; IF old.last_activity_date IS NULL OR old.last_activity_date<day-1 THEN IF old.last_activity_date=day-2 AND freezes>0 AND streak>0 THEN freezes:=freezes-1; streak:=streak+1; freeze_used:=true; ELSE streak:=1; END IF; ELSIF old.last_activity_date=day-1 THEN streak:=streak+1; END IF; INSERT INTO public.xp_transactions(user_id,xp_amount,source,source_id) VALUES(uid,5,'practice_tab',_session_key); UPDATE public.user_learning_stats SET total_xp=old.total_xp+5,current_level=public.level_for_xp(old.total_xp+5),current_streak=streak,longest_streak=greatest(old.longest_streak,streak),last_activity_date=day,streak_freezes=freezes,streak_freeze_used_at=CASE WHEN freeze_used THEN now() ELSE old.streak_freeze_used_at END,updated_at=now() WHERE user_id=uid; RETURN jsonb_build_object('awarded',5,'today_total',today_xp+5); END $$;
REVOKE ALL ON FUNCTION public.practice_eligible(uuid),public.get_mistake_questions(integer),public.get_mistake_count(),public.get_rapid_fire_items(integer),public.check_rapid_fire(uuid,integer,boolean),public.has_match_content(),public.get_match_sets(integer),public.check_match(uuid,jsonb),public.award_practice_xp(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.practice_eligible(uuid),public.get_mistake_questions(integer),public.get_mistake_count(),public.get_rapid_fire_items(integer),public.check_rapid_fire(uuid,integer,boolean),public.has_match_content(),public.get_match_sets(integer),public.check_match(uuid,jsonb),public.award_practice_xp(text,text) TO authenticated;